\begin{tikzpicture}[x=1cm,y=1cm,font=\fontsize{10}{12}\selectfont]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\coordinate (W) at (0,4); \coordinate (B) at (0,0); \coordinate (A) at (2.8,2.8); \coordinate (V) at (2.8,-1.2);
\draw[black,line width=0.8pt] (W)--(A)--(V)--(B)--cycle;
\draw[black,line width=0.8pt,->] ($(B)!0.43!(W)$)--($(B)!0.51!(W)$);
