\pic[draw=black,line width=0.4pt,angle radius=7mm] {angle=A--V--B};
\pic[angle radius=5mm,angle eccentricity=1.45,"$43^\circ$"] {angle=B--W--A};
\node[above left] at (W) {$W$}; \node[left] at (B) {$B$}; \node[right] at (A) {$A$}; \node[right] at (V) {$V$};
\end{tikzpicture}

