\begin{tikzpicture}[x=1cm,y=1cm,font=\fontsize{10}{12}\selectfont]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\coordinate (R) at (0,0); \coordinate (B) at (1,1.25); \coordinate (V) at (3.1,1.25); \coordinate (A) at (4.35,0); \coordinate (T) at (3.35,-1.25); \coordinate (S) at (1.25,-1.25);
\draw[black,line width=0.8pt] (R)--(B)--(V)--(A)--(T)--(S)--cycle; \draw[black,line width=0.8pt] (R)--(A);
\draw[black,line width=0.8pt,->] ($(S)!0.45!(R)$)--($(S)!0.55!(R)$); \draw[black,line width=0.8pt,->] ($(A)!0.45!(V)$)--($(A)!0.55!(V)$);
\foreach \t in {0.46,0.53} {\draw[black,line width=0.8pt,->] ($(R)!\t!(B)$)--($(R)!{\t+0.06}!(B)$); \draw[black,line width=0.8pt,->] ($(T)!\t!(A)$)--($(T)!{\t+0.06}!(A)$);}
\foreach \t in {0.44,0.49,0.54} {\draw[black,line width=0.8pt,->] ($(B)!\t!(V)$)--($(B)!{\t+0.04}!(V)$); \draw[black,line width=0.8pt,->] ($(R)!\t!(A)$)--($(R)!{\t+0.02}!(A)$); \draw[black,line width=0.8pt,->] ($(S)!\t!(T)$)--($(S)!{\t+0.04}!(T)$);}
\pic[draw=black,line width=0.4pt,angle radius=6mm] {angle=B--V--A};
\pic[angle radius=5mm,angle eccentricity=1.5,"$45^\circ$"] {angle=S--R--A};
\node[left] at (R) {$R$}; \node[above] at (B) {$B$}; \node[above] at (V) {$V$}; \node[right] at (A) {$A$}; \node[below] at (T) {$T$}; \node[below] at (S) {$S$};
\end{tikzpicture}
